class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Long> creatorViews = new HashMap<>();
        Map<String, Set<String>> creatorIds = new HashMap<>();

        for (int i = 0; i < creators.length; i++) {
            String creator = creators[i];
            long view = views[i];

            creatorViews.put(creator, creatorViews.getOrDefault(creator, 0L) + view);

            Set<String> idSet = creatorIds.computeIfAbsent(creator, k -> new HashSet<>());
            idSet.add(ids[i]);
        }

        List<String> topCreators = new ArrayList<>();
        long maxViews = 0;
        for (Map.Entry<String, Long> entry : creatorViews.entrySet()) {
            if (entry.getValue() > maxViews) {
                maxViews = entry.getValue();
                topCreators.clear();
                topCreators.add(entry.getKey());
            } else if (entry.getValue().equals(maxViews)) {
                topCreators.add(entry.getKey());
            }
        }

