    private void traverseAndFlip(TreeNode node, int val, int depth, Map<TreeNode, Boolean> flippedNodes) {
        if (node == null) {
            return;
        }

        // Check if the current node needs to be flipped
        if (node.val == val && depth > 0) {
            flippedNodes.put(node, true);
            depth--;
        } else if (depth <= 0) {
            flippedNodes.put(node, false);
        }

        // Recursively traverse the left and right subtrees
        traverseAndFlip(node.left, val, depth, flippedNodes);
        traverseAndFlip(node.right, val, depth, flippedNodes);
    }

