class Solution {
public:
    bool btreeGameWinningMove(TreeNode* root, int n, int x) {
        // Initialize variables to store the counts of nodes in left and right subtrees
        int leftCount = 0, rightCount = 0;

        // Helper function to count the number of nodes in a subtree
        auto countNodes = [&](TreeNode* node) -> int {
            if (!node) return 0;
            return 1 + countNodes(node->left) + countNodes(node->right);
        };

        // Traverse the tree to find the node with value x
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            TreeNode* node = q.front();
            q.pop();

            // If the current node has value x, count its left and right subtrees
            if (node->val == x) {
                leftCount = countNodes(node->left);
                rightCount = countNodes(node->right);
                break;
            }

            // Add child nodes to the queue for further traversal
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }

        // Calculate the count of nodes in the remaining part of the tree
        int remainingCount = n - leftCount - rightCount - 1;

        // Check if any of the three parts have more than half of the total nodes
        return leftCount > n / 2 || rightCount > n / 2 || remainingCount > n / 2;
    }
};

