class Solution {
public:
    int closedIsland(std::vector<std::vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        int ans = 0;

        // Use BFS to mark all connected land cells as visited
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 0) continue;

                std::queue<std::pair<int, int>> q;
                q.push({i, j});
                bool isClosed = true;

                while (!q.empty()) {
                    auto [x, y] = q.front(); q.pop();

                    // If we reach the boundary, it means the island is not closed
                    if (x <= 0 || x >= m - 1 || y <= 0 || y >= n - 1) isClosed = false;

                    grid[x][y] = 0; // Mark as visited

                    // Add adjacent land cells to the queue
                    if (x > 0 && grid[x - 1][y]) q.push({x - 1, y});
                    if (x < m - 1 && grid[x + 1][y]) q.push({x + 1, y});
                    if (y > 0 && grid[x][y - 1]) q.push({x, y - 1});
                    if (y < n - 1 && grid[x][y + 1]) q.push({x, y + 1});
                }

                // If the island is closed, increment the answer
                if (isClosed) ++ans;
            }
        }

        return ans;
    }
};

