        boolean[][] visited = new boolean[m][n];

        // Start from the top-left corner and try to reach the bottom-right corner
        return dfs(grid, visited, 0, 0);
    }

    private boolean dfs(int[][] grid, boolean[][] visited, int x, int y) {
        // Check if the current cell is out of bounds or already visited
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || visited[x][y]) {
            return false;
        }

        // Mark the current cell as visited
        visited[x][y] = true;

        // If we reached the bottom-right corner, return true
