public class Solution {
    public int minMalwareSpread(int[][] graph) {
        int n = graph.length;
        UnionFind uf = new UnionFind(n);

        // Union nodes that are connected
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (graph[i][j] == 1) {
                    uf.union(i, j);
                }
            }
        }

        // Count the size of each component
        Map<Integer, Integer> componentSize = new HashMap<>();
        for (int i = 0; i < n; i++) {
            componentSize.put(uf.find(i), componentSize.getOrDefault(uf.find(i), 0) + 1);
        }

        // Find the node with the maximum value in the same component
        int maxNode = 0;
        int maxSize = 0;
        for (int i = 0; i < n; i++) {
            int component = uf.find(i);
            if (componentSize.get(component) > maxSize) {
                maxSize = componentSize.get(component);
                maxNode = i;
            } else if (componentSize.get(component) == maxSize) {
                maxNode = Math.max(maxNode, i);
            }
        }

        return maxNode;
    }

    private static class UnionFind {
        private int[] parent;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }
    }
}

