    public int countRestrictedPaths(int n, int[][] edges, int[] restricted) {
        // Create adjacency list representation of graph
        List<List<int[]>> adjList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adjList.get(edge[0]).add(new int[]{edge[1], 1});
            adjList.get(edge[1]).add(new int[]{edge[0], 1});
        }

        // Initialize distance array with maximum possible values
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);

        // Set distance of restricted nodes to 0
        for (int node : restricted) {
            dist[node] = 0;
        }

        // Perform Dijkstra's algorithm to find shortest paths from each node
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        for (int i = 0; i < n; i++) {
            pq.offer(new int[]{i, dist[i]});
        }
        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int u = curr[0];
            int d = curr[1];

            for (int[] neighbor : adjList.get(u)) {
                int v = neighbor[0];
                int weight = neighbor[1];

                if (dist[v] > d + weight) {
                    dist[v] = d + weight;
                    pq.offer(new int[]{v, dist[v]});
                }
            }
        }

        // Count number of nodes with positive distance
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (dist[i] > 0) {
                count++;
            }
        }

        return count;
    }
}

