public class Solution {     
    public int[][] calcEquation(int[][] equations, int[] values, int[][] queries) {
        // Create a graph to represent the relationships between variables
        Map<Integer, List<int[]>> graph = new HashMap<>();
        for (int i = 0; i < equations.length; i++) {
            int u = equations[i][0];
            int v = equations[i][1];
            int w = values[i];

            // Add edges to the graph
            if (!graph.containsKey(u)) {
                graph.put(u, new ArrayList<>());
            }
            if (!graph.containsKey(v)) {
                graph.put(v, new ArrayList<>());
            }
            graph.get(u).add(new int[]{v, w});
            graph.get(v).add(new int[]{u, 1 / w});
        }

        // Initialize the result array
        int[][] result = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            int u = queries[i][0];
            int v = queries[i][1];

            // Check if both variables exist in the graph
            if (!graph.containsKey(u) || !graph.containsKey(v)) {
                result[i][0] = -1;
                continue;
            }

            // Perform DFS to find the path from u to v
            boolean[] visited = new boolean[graph.size()];
            int[] path = new int[graph.size()];
            if (dfs(graph, u, v, visited, path, 0)) {
                // Calculate the value of the expression
                int value = 1;
                for (int j = 0; j < path.length - 1; j++) {
                    int[] edge = graph.get(path[j]).stream().filter(e -> e[0] == path[j + 1]).findFirst().orElse(null);
                    value *= edge[1];
                }
                result[i][0] = value;
            } else {
                result[i][0] = -1;
            }
        }
        return result;
    }

    private boolean dfs(Map<Integer, List<int[]>> graph, int u, int v, boolean[] visited, int[] path, int index) {
        if (visited[u]) {
            return false;
        }
        visited[u] = true;
        path[index] = u;

        if (u == v) {
            return true;
        }

        for (int[] neighbor : graph.get(u)) {
            if (dfs(graph, neighbor[0], v, visited, path, index + 1)) {
                return true;
            }
        }
        visited[u] = false;
        return false;
    }
}

