import java.util.*;

public class Solution {
    public int maxNodesWithoutRestricted(int n, int[][] edges, int[] restricted) {
        // Create a graph representation using adjacency list
        Map<Integer, List<Integer>> tree = new HashMap<>();
        Set<Integer> blockedNodes = new HashSet<>();
        for (int r : restricted) blockedNodes.add(r);

        for (int[] edge : edges) {
            tree.putIfAbsent(edge[0], new ArrayList<>());
            tree.putIfAbsent(edge[1], new ArrayList<>());
            tree.get(edge[0]).add(edge[1]);
            tree.get(edge[1]).add(edge[0]);
        }

        int[] maxNodes = new int[1];

        // Use DFS to traverse the graph and count the number of nodes
        dfs(0, 1, -1, tree, blockedNodes, maxNodes);
        return maxNodes[0];
    }

    private void dfs(int node, int depth, int parent, Map<Integer, List<Integer>> tree, Set<Integer> blockedNodes, int[] maxNodes) {
        if (blockedNodes.contains(node)) return;
        maxNodes[0] = Math.max(maxNodes[0], depth);
        for (int child : tree.get(node)) {
            if (child != parent) dfs(child, depth + 1, node, tree, blockedNodes, maxNodes);
        }
    }

    // New function to find the maximum area of land in a grid
    public int maxAreaOfLand(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        int maxArea = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j] && grid[i][j] == 1) {
                    int area = bfs(i, j, grid, visited);
                    maxArea = Math.max(maxArea, area);
                }
            }
        }

        return maxArea;
    }

    private int bfs(int x, int y, int[][] grid, boolean[][] visited) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{x, y});
        visited[x][y] = true;
        int area = 1;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int row = current[0];
            int col = current[1];

            int[] dx = {0, 0, 1, -1};
            int[] dy = {1, -1, 0, 0};

            for (int i = 0; i < 4; i++) {
                int newX = row + dx[i];
                int newY = col + dy[i];

                if (newX >= 0 && newX < grid.length && newY >= 0 && newY < grid[0].length && !visited[newX][newY] && grid[newX][newY] == 1) {
                    queue.offer(new int[]{newX, newY});
                    visited[newX][newY] = true;
                    area++;
                }
            }
        }

        return area;
    }
}

