            return score;
        }

        // Recursive function to find maximum score
        int dfs(List<String> words, int index, int[] count) {
            if (index >= words.size()) {
                return 0;
            }

            String word = words.get(index);
            int score = 0;
            boolean canTake = true;
            for (char c : word.toCharArray()) {
                if (--count[c - 'a'] < 0) {
                    canTake = false;
                    break;
                }
                score += vals[c - 'a'];
            }

            int take = 0;
            if (canTake) {
                take = score + dfs(words, index + 1, count);
            }

            for (char c : word.toCharArray()) {
                count[c - 'a']++;
            }

            int skip = dfs(words, index + 1, count);
            return Math.max(take, skip);
        }

        // Convert input arrays to lists
        List<String> wordList = new ArrayList<>();
        for (String word : words) {
            wordList.add(word);
        }

        // Call recursive function with initial parameters
        return dfs(wordList, 0, count);
    }
