    for (char c : letters) {
        letterCount[c - 'a']++;
    }

    int maxScore = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        int[] currentLetterCount = Arrays.copyOf(letterCount, 26);
        int currentScore = 0;
        boolean valid = true;
