public class Solution {
    public int findLUSlength(String[] strs) {
        // Create a list to store all possible substrings
        List<String> substrings = new ArrayList<>();

        // Iterate over each string in the input array
        for (String str : strs) {
            // Generate all possible substrings of the current string
            for (int i = 0; i < str.length(); i++) {
                for (int j = i + 1; j <= str.length(); j++) {
                    substrings.add(str.substring(i, j));
                }
            }
        }

        // Sort the list of substrings in descending order based on their lengths
        Collections.sort(substrings, (a, b) -> b.length() - a.length());

        // Iterate over each substring in the sorted list
        for (String substring : substrings) {
            // Check if the current substring is unique among all other substrings
            boolean isUnique = true;
            for (String otherSubstring : substrings) {
                if (!substring.equals(otherSubstring) && otherSubstring.contains(substring)) {
                    isUnique = false;
                    break;
                }
            }

            // If the current substring is unique, return its length
            if (isUnique) {
                return substring.length();
            }
        }

        // If no unique substring is found, return -1
        return -1;
    }
}

