        return a.first > b.first;
    };

    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, decltype(listComparator)> minHeap(listComparator);

    int maxVal = std::numeric_limits<int>::min();
    for (int i = 0; i < nums.size(); i++) {
