    int minRange = std::numeric_limits<int>::max();
    int start = -1, end = -1;

    while (minHeap.size() == nums.size()) {
        auto entry = minHeap.top();
        minHeap.pop();
        int val = entry.first;
        int listIdx = entry.second;
        int range = maxVal - val;

