public class Solution {
    public int maxSumOfThreeSubarrays(int[] nums) {
        int n = nums.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        int[][] dp = new int[4][n];
        for (int k = 1; k <= 3; k++) {
            for (int i = k - 1; i < n; i++) {
                dp[k][i] = Math.max(dp[k][i - 1], prefixSum[i + 1] - prefixSum[i + 1 - k] + dp[k - 1][i - k]);
            }
        }

        return dp[3][n - 1];
    }
}

