    int minimumWhiteTiles(std::vector<std::vector<int>>& tiles, int carpetLen) {
        // Sort the tiles based on their starting position
        std::sort(tiles.begin(), tiles.end());

        // Initialize variables to keep track of the number of white tiles and the current position in the tiles array
