import java.util.List;

public class Solution {
    public int maxSumAfterPartitioning(int[] A, int K) {
        int N = A.length;
        int[] dp = new int[N + 1];

        for (int i = 1; i <= N; ++i) {
            int curMax = 0;
            for (int k = 1; k <= Math.min(K, i); ++k) {
                curMax = Math.max(curMax, A[i - k]);
                dp[i] = Math.max(dp[i], dp[i - k] + curMax * k);
            }
        }

        return dp[N];
    }
}

