class Solution {
public:
    long long countRangeSum(vector<int>& nums, int lower, int upper) {
        vector<long long> sums(nums.size() + 1);
        for (int i = 0; i < nums.size(); ++i)
            sums[i + 1] = sums[i] + nums[i];

        return mergeSort(sums, 0, sums.size(), lower, upper);
    }

private:
    long long mergeSort(vector<long long>& sums, int l, int r, int lower, int upper) {
        if (l >= r) return 0;
        int mid = (l + r) / 2;
        long long ret = mergeSort(sums, l, mid, lower, upper) + mergeSort(sums, mid + 1, r, lower, upper);
        int j = mid + 1, k = mid + 1, t = r;
        vector<long long> cache(r - l + 1);
        for (int i = l, p = 0; i <= mid; ++i, ++p) {
            while (k <= t && sums[k] - sums[i] > upper) ++k;
            while (j <= t && sums[j] - sums[i] >= lower) ++j;
            while (t >= mid + 1 && sums[t] >= sums[i]) cache[p + --t - l] = sums[t];
            cache[p + t - l] = sums[i];
            ret += k - j;
        }
        copy(cache.begin(), cache.end() - (r - t), sums.begin() + l);
        return ret;
    }
};

