public class Solution {
    public int findShortestPath(int n, List<List<Integer>> edges) {
        // Create adjacency list representation of graph
        Map<Integer, List<Integer>> adjList = new HashMap<>();
        for (int i = 0; i < n; i++) {
            adjList.put(i, new ArrayList<>());
        }

        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            adjList.get(u).add(v);
            adjList.get(v).add(u);
        }

        // Initialize distance array with infinity
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);

        // Perform BFS to find shortest path from node 0 to all other nodes
        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);
        dist[0] = 0;

        while (!queue.isEmpty()) {
            int u = queue.poll();

            for (int v : adjList.get(u)) {
                if (dist[v] == Integer.MAX_VALUE) {
                    dist[v] = dist[u] + 1;
                    queue.add(v);
                }
            }
        }

        // Find maximum distance in distance array
        int maxDist = 0;
        for (int d : dist) {
            maxDist = Math.max(maxDist, d);
        }

        return maxDist;
    }
}

