        int visitedNodes = 0;
        int maxColorValue = 0;

        while (!queue.isEmpty()) {
            int node = queue.removeLast();
            int color = colors.charAt(node) - 'a';
            visitedNodes++;

            for (int neighbor : adj.get(node)) {
