        vector<int> in_degree(k), order;
        vector<unordered_set<int>> graph(k);
        for (const auto& cond : conditions) {
            graph[cond[0] - 1].insert(cond[1] - 1);
            ++in_degree[cond[1] - 1];
        }
        queue<int> q;
        for (int i = 0; i < k; ++i)
            if (in_degree[i] == 0) q.push(i);
        while (!q.empty()) {
            if (q.size() > 1) return {};
            int cur = q.front(); q.pop();
            order.emplace_back(cur);
            for (int next : graph[cur]) {
                --in_degree[next];
                if (in_degree[next] == 0) q.push(next);
            }
        }
        return order.size() == k ? order : vector<int>();
    }
};

