def minTime(colors: str, edges: List[List[int]]) -> int:
    n = len(colors)
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for u, v in edges:
        graph[u].append(v)
        indegree[v] += 1

    queue = deque()
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    time = [0] * n
    while queue:
        node = queue.popleft()
        time[node] += 1
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if colors[neighbor] != colors[node]:
                time[neighbor] = max(time[neighbor], time[node])
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return max(time)

