    public int minOperations(int[] nums, int[] numsDivide) {
        // Find the greatest common divisor (GCD) of all elements in numsDivide
        int gcd = numsDivide[0];
        for (int num : numsDivide) {
            gcd = gcd(gcd, num);
        }

