            if (gcd % nums[i] == 0) {
                return i;
            }
        }

        // If no such element is found, return the length of the array
        return nums.length;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

