import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int minMoves(List<Integer> nums, int k) {
        // Sort the list in ascending order
        Collections.sort(nums);

        // Initialize variables to keep track of the minimum number of moves and the current position
        int minMoves = Integer.MAX_VALUE;
        int currentPosition = 0;

        // Iterate over each element in the sorted list
        for (int i = 0; i < nums.size(); i++) {
            // Calculate the number of moves required to move all elements before the current position to the current position
            int movesBeforeCurrentPosition = 0;
            for (int j = 0; j < i; j++) {
                movesBeforeCurrentPosition += Math.abs(nums.get(j) - nums.get(i));
            }

            // Calculate the number of moves required to move all elements after the current position to the current position
            int movesAfterCurrentPosition = 0;
            for (int j = i + 1; j < nums.size(); j++) {
                movesAfterCurrentPosition += Math.abs(nums.get(j) - nums.get(i));
            }

            // Update the minimum number of moves if the current position results in fewer moves
            if (movesBeforeCurrentPosition + movesAfterCurrentPosition < minMoves) {
                minMoves = movesBeforeCurrentPosition + movesAfterCurrentPosition;
                currentPosition = i;
            }
        }

        // Return the minimum number of moves required to make all elements equal
        return minMoves;
    }
}

