import java.util.List;

public List<Integer> findSubstring(String s, String[] words) {
    List<Integer> result = new ArrayList<>();
    if (s == null || words == null || words.length == 0) return result;

    int wordLength = words[0].length();
    int numWords = words.length;
    int totalLength = wordLength * numWords;
    HashMap<String, Integer> wordCount = new HashMap<>();

    // Count the frequency of each word in the pattern
    for (String word : words) {
        wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
    }

    // Iterate over the string with a sliding window approach
    for (int i = 0; i <= s.length() - totalLength; i++) {
        HashMap<String, Integer> seenWords = new HashMap<>();
        int j = 0;
        while (j < numWords) {
            String currentWord = s.substring(i + j * wordLength, i + (j + 1) * wordLength);
            if (!wordCount.containsKey(currentWord)) break;
            seenWords.put(currentWord, seenWords.getOrDefault(currentWord, 0) + 1);
            if (seenWords.get(currentWord) > wordCount.get(currentWord)) break;
            j++;
        }
        if (j == numWords) result.add(i);
    }
    return result;
}

