public class Solution {
    public int minMeetingRooms(int[][] intervals) {
        if (intervals.length == 0) return 0;

        // Sort intervals based on their start time
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));

        // Initialize variables to keep track of the number of rooms needed and the end time of the last meeting
        int rooms = 0;
        int end = -1;

        // Iterate over each interval
        for (int[] interval : intervals) {
            // If the current meeting starts after the previous meeting ends, we can reuse the same room
            if (interval[0] >= end) {
                end = interval[1];
            } else {
                // Otherwise, we need a new room
                rooms++;
                end = Math.max(end, interval[1]);
            }
        }

        return rooms + 1;
    }
}

