public int minCost(int[][] costs) {
    if (costs == null || costs.length == 0) {
        return 0;
    }

    int n = costs.length;
    int m = costs[0].length;

    // Initialize the dp array with the first row of costs
    int[] dp = new int[m];
    System.arraycopy(costs[0], 0, dp, 0, m);

    // Iterate over each row of costs
    for (int i = 1; i < n; i++) {
        // Create a temporary array to store the updated values of dp
        int[] temp = new int[m];

        // Iterate over each column of costs
        for (int j = 0; j < m; j++) {
            // Calculate the minimum cost to reach the current cell
            int minCost = Integer.MAX_VALUE;
            for (int k = 0; k < m; k++) {
                if (k != j) {
                    minCost = Math.min(minCost, dp[k]);
                }
            }

            // Update the value of dp[j]
            temp[j] = costs[i][j] + minCost;
        }

        // Update the dp array with the temporary array
        dp = temp;
    }

    // Return the minimum cost to paint all houses
    return Arrays.stream(dp).min().getAsInt();
}

