    public List<Integer> numIslands2(int m, int n, int[][] positions) {
        visited = new boolean[m][n];
        for (int[] pos : positions) {
            int x = pos[0];
            int y = pos[1];
            if (!visited[x][y]) {
                result.add(1);
                visited[x][y] = true;
            } else {
                result.add(result.get(result.size() - 1));
                continue;
            }
            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                if (nx < 0 || nx >= m || ny < 0 || ny >= n || !visited[nx][ny])
                    continue;
                union(x * n + y, nx * n + ny);
            }
        }
        return result;
    }

    private void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA != rootB) {
            result.set(result.size() - 1, result.get(result.size() - 1) - 1);
            visited[rootA / 5][rootA % 5] = false;
            visited[rootB / 5][rootB % 5] = false;
            visited[a / 5][a % 5] = true;
            visited[b / 5][b % 5] = true;
        }
    }

    private int find(int a) {
        if (a == visited[a / 5][a % 5])
            return a;
        return visited[a / 5][a % 5] = find(visited[a / 5][a % 5]);
    }
