import java.util.*;

public class Solution {
    public List<Integer> findOrder(int n, int[][] edges) {
        List<Integer> res = new ArrayList<>();
        Map<Integer, Set<Integer>> map = new HashMap<>();
        int[] degree = new int[n];

        // Build graph
        for (int[] edge : edges) {
            int from = edge[1], to = edge[0];
            degree[to]++;
            map.computeIfAbsent(from, o -> new HashSet<>()).add(to);
        }

        // Topological sort
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (degree[i] == 0) queue.offer(i);
        }

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            res.add(cur);

            if (map.containsKey(cur)) {
                for (int neighbor : map.get(cur)) {
                    if (--degree[neighbor] == 0) queue.offer(neighbor);
                }
            }
        }

        return res.size() == n ? res : Collections.emptyList();
    }
}

