    public List<List<Integer>> palindromePairs(String[] words) {
        List<List<Integer>> result = new ArrayList<>();
        if (words == null || words.length == 0) {
            return result;
        }

        // Create a map to store the indices of each word
        Map<String, Integer> wordMap = new HashMap<>();
        for (int i = 0; i < words.length; i++) {
            wordMap.put(words[i], i);
        }

        // Iterate over each word in the input array
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            int n = word.length();

            // Check all possible prefixes and suffixes of the current word
            for (int j = 0; j <= n; j++) {
                String prefix = word.substring(0, j);
                String suffix = word.substring(j);

                // Check if the reverse of the prefix exists in the map
                String reversedPrefix = new StringBuilder(prefix).reverse().toString();
                if (wordMap.containsKey(reversedPrefix) && !prefix.equals(word) && wordMap.get(reversedPrefix) != i) {
                    List<Integer> pair = new ArrayList<>();
                    pair.add(i);
                    pair.add(wordMap.get(reversedPrefix));
                    result.add(pair);
                }

                // Check if the reverse of the suffix exists in the map
                String reversedSuffix = new StringBuilder(suffix).reverse().toString();
                if (wordMap.containsKey(reversedSuffix) && !suffix.equals(word) && wordMap.get(reversedSuffix) != i) {
                    List<Integer> pair = new ArrayList<>();
                    pair.add(wordMap.get(reversedSuffix));
                    pair.add(i);
                    result.add(pair);
                }
            }
        }

        return result;
    }
