    def palindromePairs(self, words: List[str]) -> List[List[int]]:
        word_dict = {word: i for i, word in enumerate(words)}
        valid_pals = []

        for word, k in word_dict.items():
            N = len(word)

            for j in range(N+1):
                pref = word[:j]
                suf = word[j:]

                if self.isPalin(pref):
                    back = suf[::-1]
                    if back != word and back in word_dict:
                        valid_pals.append([word_dict[back], k])

                if j != N and self.isPalin(suf):
                    back = pref[::-1]
                    if back != word and back in word_dict:
                        valid_pals.append([k, word_dict[back]])
        return valid_pals

    def isPalin(self, word):
        return word == word[::-1]

