    private static String abbreviate(String target, List<String> dictionary) {
        if (target == null || target.isEmpty()) {
            return "";
        }

        for (String word : dictionary) {
            if (target.startsWith(word)) {
                return abbreviate(target.substring(word.length()), dictionary);
            }
        }

        StringBuilder result = new StringBuilder();
        int count = 0;
        char prevChar = target.charAt(0);

        for (char c : target.toCharArray()) {
            if (c == prevChar) {
                count++;
            } else {
                if (count > 0) {
                    result.append(count);
                }
                result.append(prevChar);
                count = 1;
                prevChar = c;
            }
        }

        if (count > 0) {
            result.append(count);
        }
        result.append(prevChar);

        return result.toString();
    }
