            if i == len(word): return '' if not count else str(count)
            elif word[i].isalpha(): return (str(count) + word[i]) if count > 0 else word[i] + abbreviate(word, i+1, 0)
            else: return abbreviate(word, i+1, count+1)

        def match(word, abbr):
            i, j = 0, 0
            while i < len(word) and j < len(abbr):
                if abbr[j].isdigit():
                    if abbr[j] == '0': return False  # leading zero
                    num = 0
                    while j < len(abbr) and abbr[j].isdigit():
                        num = num * 10 + int(abbr[j])
                        j += 1
                    i += num
                else:
                    if word[i] != abbr[j]: return False
                    i, j = i + 1, j + 1
            return i == len(word) and j == len(abbr)

        res = []
        for w in dictionary:
            if len(w) != len(target): continue
            if match(w, abbreviate(w)): res.append(w)
