import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public int minMutation(String start, String end, String[] bank) {
        Set<String> dict = new HashSet<>();
        for (String gene : bank) {
            dict.add(gene);
        }

        if (!dict.contains(end)) return -1;

        Queue<String> queue = new LinkedList<>();
        queue.offer(start);
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; ++i) {
                String currentGene = queue.poll();
                if (currentGene.equals(end)) return steps;

                char[] charArray = currentGene.toCharArray();
                for (int j = 0; j < charArray.length; ++j) {
                    char originalChar = charArray[j];
                    for (int k = 0; k < 4; ++k) {
                        charArray[j] = getNucleotide(k);
                        String newGene = new String(charArray);
                        if (dict.remove(newGene)) {
                            queue.offer(newGene);
                        }
                    }
                    charArray[j] = originalChar;
                }
            }
            ++steps;
        }
        return -1;
    }

    private char getNucleotide(int index) {
        switch (index) {
            case 0:
                return 'A';
            case 1:
                return 'C';
            case 2:
                return 'G';
            default:
                return 'T';
        }
    }
}

