import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int minMeetingRooms(int[][] intervals) {
        if (intervals.length == 0) return 0;

        // Sort intervals based on start time
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));

        // Use a priority queue to keep track of meeting rooms
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        pq.add(intervals[0][1]);

        for (int i = 1; i < intervals.length; i++) {
            // If the current meeting starts after the earliest ending meeting room,
            // reuse that room
            if (intervals[i][0] >= pq.peek()) {
                pq.poll();
            }

            // Add the current meeting's end time to the priority queue
            pq.add(intervals[i][1]);
        }

        // The size of the priority queue represents the minimum number of meeting rooms needed
        return pq.size();
    }
}

