def sequenceReconstruction(nums, sequences):
    graph = {i: [] for i in range(1, len(nums)+1)}
    indegree = {i: 0 for i in range(1, len(nums)+1)}

    for seq in sequences:
        for i in range(len(seq)-1):
            graph[seq[i]].append(seq[i+1])
            indegree[seq[i+1]] += 1

    q = deque([node for node in indegree if indegree[node] == 0])
    result = []

    while q:
        if len(q) > 1:
            return False
        curr = q.popleft()
        result.append(curr)
        for neighbor in graph[curr]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                q.append(neighbor)

    return result == nums

