    public int findTargetSumWays(int[] nums, int S) {
        // Initialize a list to store all possible sums
        List<Integer> sumList = new ArrayList<>();
        sumList.add(nums[0]);

        // Iterate through the remaining numbers in the array
        for (int i = 1; i < nums.length; i++) {
            List<Integer> newSumList = new ArrayList<>();

            // For each number, calculate all possible sums with addition and subtraction
            for (int sum : sumList) {
                newSumList.add(sum + nums[i]);
                newSumList.add(sum - nums[i]);
            }

            // Update the list of possible sums
            sumList = newSumList;
        }

        // Count the number of ways to achieve the target sum
        int count = 0;
        for (int sum : sumList) {
            if (sum == S) {
                count++;
            }
        }

        return count;
    }
}

