from collections import defaultdict, deque

def schedule(courses):
    adj = defaultdict(list)
    inDegree = [0] * 4

    for course in courses:
        adj[course[1]].append(course[0])
        inDegree[course[0]] += 1

    q = deque([i for i in range(4) if inDegree[i]==0])
    result = []

    while q:
        currCourse = q.popleft()
        result.append(currCourse)

        for nextCourse in adj[currCourse]:
            inDegree[nextCourse] -= 1
            if inDegree[nextCourse] == 0:
                q.append(nextCourse)

    return len(result)

