import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<List<Integer>> getPermutation(int n, int k) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> current = new ArrayList<>();
        boolean[] used = new boolean[n + 1];
        backtrack(result, current, used, n, k);
        return result;
    }

    private void backtrack(List<List<Integer>> result, List<Integer> current, boolean[] used, int n, int k) {
        if (current.size() == n) {
            result.add(new ArrayList<>(current));
            return;
        }

        for (int i = 1; i <= n; i++) {
            if (!used[i]) {
                current.add(i);
                used[i] = true;
                backtrack(result, current, used, n, k - 1);
                used[i] = false;
                current.remove(current.size() - 1);
            }
        }
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        List<List<Integer>> result = solution.getPermutation(3, 1);
        System.out.println(result); // [[1,2,3]]
    }
}

