import java.util.PriorityQueue;

public class Solution {
    public int kthSmallestPrimeFraction(int[] arr, int k) {
        // Create a priority queue to store fractions in ascending order
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> arr[a[0]] * arr[b[1]] - arr[a[1]] * arr[b[0]]);

        // Add all possible fractions to the priority queue
        for (int i = 0; i < arr.length - 1; i++) {
            pq.offer(new int[]{i, arr.length - 1});
        }

        // Remove elements from the priority queue until we reach the k-th smallest fraction
        while (--k > 0) {
            int[] tmp = pq.poll();
            if (--tmp[1] > tmp[0]) {
                pq.offer(tmp);
            }
        }

        // Return the numerator and denominator of the k-th smallest fraction
        return new int[]{arr[pq.peek()[0]], arr[pq.peek()[1]]};
    }

