        }

        return image;
    }

private:
    void fill(vector<vector<int>>& image, int i, int j, int oldColor, int newColor, int rows, int cols) {
        // Check boundaries
        if (i < 0 || i >= rows || j < 0 || j >= cols) {
            return;
        }

        // If the current pixel is not the old color, no need to fill it
        if (image[i][j] != oldColor) {
            return;
        }

        // Fill the current pixel with the new color
        image[i][j] = newColor;

        // Recursively fill the neighboring pixels
        fill(image, i-1, j, oldColor, newColor, rows, cols); // up
        fill(image, i+1, j, oldColor, newColor, rows, cols); // down
        fill(image, i, j-1, oldColor, newColor, rows, cols); // left
        fill(image, i, j+1, oldColor, newColor, rows, cols); // right
    }
