class Solution {
public:
    vector<string> basicCalculatorIV(string expression, vector<string>& evalvars, vector<int>& evalints) {
        // Create a map to store the evaluated variables
        unordered_map<string, int> vars;

        // Evaluate each variable in evalvars with its corresponding value from evalints
        for (int i = 0; i < evalvars.size(); i++) {
            vars[evalvars[i]] = evalints[i];
        }

        // Split the input expression into tokens
        vector<string> tokens;
        string token;
        for (char c : expression) {
            if (c == ' ') continue;
            if (c == '+' || c == '-' || c == '*') {
                tokens.push_back(token);
                tokens.push_back(string(1, c));
                token.clear();
            } else {
                token += c;
            }
        }
        tokens.push_back(token);

        // Use a stack to evaluate the expression
        vector<string> stack;
        for (string token : tokens) {
            if (token == "+" || token == "-" || token == "*") {
                // Pop two operands from the stack
                string op2 = stack.back();
                stack.pop_back();
                string op1 = stack.back();
                stack.pop_back();

                // Perform the operation and push the result back onto the stack
                if (token == "+") {
                    stack.push_back(op1 + "+" + op2);
                } else if (token == "-") {
                    stack.push_back(op1 + "-" + op2);
                } else { // token == "*"
                    stack.push_back(op1 + "*" + op2);
                }
            } else {
                // Push the operand onto the stack
                stack.push_back(token);
            }
        }

        // The final result is the only element left on the stack
        return vector<string>(stack.begin(), stack.end());
    }
};

