public boolean twoSumBSTs(TreeNode root1, TreeNode root2, int target) {
    Set<Integer> set = new HashSet<>();
    populateSet(root1, set);
    return findPair(root2, target, set);
}

private void populateSet(TreeNode node, Set<Integer> set) {
    if (node == null) return;
    set.add(node.val);
    populateSet(node.left, set);
    populateSet(node.right, set);
}

private boolean findPair(TreeNode node, int target, Set<Integer> set) {
    if (node == null) return false;
    if (set.contains(target - node.val)) return true;
    return findPair(node.left, target, set) || findPair(node.right, target, set);
}
